import { __ } from '@wordpress/i18n';

export function NoticeBanner({ type, message, onDismiss }) {
	return (
		<div className={`wppo-notice wppo-notice--${type}`} role="alert" aria-live={type === 'error' ? 'assertive' : 'polite'}>
		<span>{message}</span>
		{onDismiss && (
			<button type="button" onClick={onDismiss} aria-label={__('Dismiss', 'performance-optimisation')}>
				{__('Dismiss', 'performance-optimisation')}
			</button>
		)}
		</div>
	);
}
